protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, null, 0, new ArrayList<>());
    }

    // Find a starting vertex
    V start = null;
    for (E edge : tour) {
        start = graph.getEdgeSource(edge);
        break;
    }

    // Build the path by following edges
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    V current = start;
    vertices.add(current);

    Set<E> remainingEdges = new HashSet<>(tour);

    while (!remainingEdges.isEmpty()) {
        E nextEdge = null;
        for (E edge : remainingEdges) {
            if (graph.getEdgeSource(edge).equals(current)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            // Try finding an edge where current is the target (for undirected graphs)
            for (E edge : remainingEdges) {
                if (graph.getEdgeTarget(edge).equals(current)) {
                    nextEdge = edge;
                    break;
                }
            }
        }

        if (nextEdge == null) {
            throw new IllegalArgumentException("Cannot form a valid tour from the given edge set");
        }

        edges.add(nextEdge);
        remainingEdges.remove(nextEdge);

        V nextVertex = graph.getEdgeTarget(nextEdge);
        if (nextVertex.equals(current)) {
            // Self-loop, stay at the same vertex
            nextVertex = graph.getEdgeSource(nextEdge);
        }

        current = nextVertex;
        vertices.add(current);
    }

    return new GraphPathImpl<>(graph, start, current, edges.size(), edges);
}

