private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b = bb.get(i) & 0xFF;
    if (b < 0x80) {
        sb.append((char) b);
        return i + 1;
    } else if (b < 0xC0) {
        // Unexpected continuation byte
        sb.append('\uFFFD');
        return i + 1;
    } else if (b < 0xE0) {
        // 2-byte sequence
        if (i + 1 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b2 = bb.get(i + 1) & 0xFF;
        if ((b2 & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int codePoint = ((b & 0x1F) << 6) | (b2 & 0x3F);
        sb.append((char) codePoint);
        return i + 2;
    } else if (b < 0xF0) {
        // 3-byte sequence
        if (i + 2 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
