public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Normalize the path by removing trailing slash if present
    String normalizedPath = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;

    // If relativePath starts with "/", it's an absolute path, return it as is
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Combine the path and relativePath
    String combined = normalizedPath + "/" + relativePath;

    // Normalize the combined path by resolving "." and ".." segments
    String[] parts = combined.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    for (String part : parts) {
        if (part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else if (!part.isEmpty()) {
            stack.push(part);
        }
    }

    // Reconstruct the path
    StringBuilder result = new StringBuilder();
    while (!stack.isEmpty()) {
        if (result.length() > 0) {
            result.insert(0, "/");
        }
        result.insert(0, stack.pop());
    }

    // If the original path was absolute (starts with /), ensure the result starts with /
    if (path.startsWith("/")) {
        result.insert(0, "/");
    }

    return result.toString();
}

