public void abbreviate(final int nameStart, final StringBuffer buf) {
    int i = nameStart;
    // Skip leading whitespace
    while (i < name.length() && Character.isWhitespace(name.charAt(i))) {
        i++;
    }
    if (i >= name.length()) {
        return;
    }
    // Append first character
    char first = name.charAt(i);
    buf.append(first);
    i++;
    // Skip whitespace after first character
    while (i < name.length() && Character.isWhitespace(name.charAt(i))) {
        i++;
    }
    // Find the next non-whitespace character (start of last name)
    if (i < name.length()) {
        char last = name.charAt(i);
        buf.append('.');
        buf.append(last);
    }
}

