static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    // Convert to a date-like representation
    // We need to find the start of the "bucket" for the given dayStep
    // The bucket starts at day 1 of the month, and each bucket is dayStep days long
    // So the bucket index is (day - 1) / dayStep
    // The start day of the bucket is 1 + bucketIndex * dayStep

    long bucketIndex = (day - 1) / dayStep;
    long startDay = 1 + bucketIndex * dayStep;

    // Check if startDay exceeds the number of days in the month
    // If so, we need to handle month overflow
    int daysInMonth = getDaysInMonth(year, month);
    if (startDay > daysInMonth) {
        // This shouldn't happen in normal cases, but handle it
        startDay = daysInMonth;
    }

    return year * 10000 + month * 100 + startDay;
}

